<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\PrayerRequest; use Illuminate\Http\Request;
class PrayerController extends Controller { public function index(Request $r){return response()->json(PrayerRequest::where('user_id',$r->user()->id)->latest()->paginate(20));} public function store(Request $r){$d=$r->validate(['subject'=>'required|string|max:160','message'=>'required|string|max:5000','visibility'=>'required|in:private,pastoral_team,public_anonymous','organisation_unit_id'=>'nullable|exists:organisation_units,id']); $keywords=['abuse','suicide','self harm','violence','rape']; $text=strtolower($d['subject'].' '.$d['message']); $d['requires_safeguarding_review']=collect($keywords)->contains(fn($k)=>str_contains($text,$k)); $d['user_id']=$r->user()->id; $p=PrayerRequest::create($d); return response()->json(['message'=>'Your prayer request has been submitted safely.','prayer_request'=>$p],201);}}